9	import net.officefloor.hq.app.Audit;
10	import net.officefloor.hq.app.rollup.RollupService;
11	import net.officefloor.hq.app.sheet.SheetService;
12	import org.springframework.dao.DataIntegrityViolationException;
13	import org.springframework.http.HttpStatus;
14	import org.springframework.orm.ObjectOptimisticLockingFailureException;
15	import org.springframework.stereotype.Service;
16	import org.springframework.transaction.annotation.Transactional;
17	import org.springframework.web.server.ResponseStatusException;
18	
19	/** The people kept on a sheet. */
20	@Service
21	public class PersonService {
22	
23	    private final PersonRepository people;
24	    private final PatronRepository patrons;
25	    private final SheetService sheets;
26	    private final RollupService rollup;
27	    private final Audit audit;
28	
29	    public PersonService(PersonRepository people, PatronRepository patrons, SheetService sheets, RollupService rollup, Audit audit) {
30	        this.people = people;
31	        this.patrons = patrons;
32	        this.sheets = sheets;
33	        this.rollup = rollup;
34	        this.audit = audit;
35	    }
36	
37	    @Transactional(readOnly = true)
38	    public List<Person> list(String sheetId) {
39	        return people.findBySheetIdOrderByIdAsc(sheetId);
40	    }
41	
42	    /** The sheet's today, which the grade a person is listed with is in force on. */
43	    @Transactional
44	    public LocalDate today(String sheetId) {
45	        return sheets.load(sheetId).getToday();
46	    }
47	
48	    /** Adds the person with no terms of their own. */
49	    @Transactional
50	    public Person add(String by, String sheetId, String name, String grade) {
51	        return add(by, sheetId, name, grade, null);
52	    }
53	
54	    /**
55	     * Adds the person with their own terms (null: none); the grade they are given first applies from the beginning
56	     * of time.
57	     */
58	    @Transactional
59	    public Person add(String by, String sheetId, String name, String grade, Integer terms) {
60	        return add(by, sheetId, name, grade, terms, null);
61	    }
62	
63	    /**
64	     * Adds the person with their own terms (null: none) and contact (blank or null: none); the grade they are given
65	     * first applies from the beginning of time. Refused when another person on the sheet has the contact.
66	     */
67	    @Transactional
68	    public Person add(String by, String sheetId, String name, String grade, Integer terms, String contact) {
69	        LocalDate today = sheets.load(sheetId).getToday();
70	        RollupService.Snapshot before = rollup.snapshot(sheetId);
71	        String trimmed = name.strip();
72	        if (people.nameOrAliasInUse(sheetId, trimmed)) {
73	            throw nameInUse();
74	        }
75	        String key = contactKey(contact);
76	        if (key != null && people.existsBySheetIdAndContact(sheetId, key)) {
77	            throw contactInUse();
78	        }
79	        Person person = new Person(sheetId, trimmed, grade, today);
80	        person.setTerms(terms);
81	        person.setContact(key);
82	        Person added = save(person);
83	        audit.recordOnCommit(record("PERSON_ADDED", by, added, today(sheetId))
84	                + (terms != null ? " terms=" + terms : "")
85	                + (key != null ? " contact=" + key : ""));
86	        rollup.recordChanges(by, sheetId, before);
87	        return added;
88	    }
89	
90	    /**
91	     * Saves an edit made from the given version of the person; refused when it has been saved since. The grade is
92	     * recorded from the from-date (missing: the sheet's today), keeping the ones already recorded, except that an
93	     * edit leaving the grade in force today as it is, with no from-date, records nothing. The person's own terms are
94	     * set to the given ones (null: none), and their contact to the given one (blank or null: none), refused when
95	     * another person on the sheet has it.
96	     */
97	    @Transactional
98	    public Person update(String by, String sheetId, Long id, long version, String name, String grade,
99	            LocalDate gradeFrom, Integer terms, String contact) {
100	        LocalDate today = today(sheetId);
101	        RollupService.Snapshot before = rollup.snapshot(sheetId);
102	        Person person = people.findByIdAndSheetId(id, sheetId)
103	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
104	        if (person.getVersion() != version) {
105	            throw stale();
106	        }
107	        String trimmed = name.strip();
108	        if (people.existsBySheetIdAndNameIgnoreCaseAndIdNot(sheetId, trimmed, id)
109	                || people.findBySheetIdAndAlias(sheetId, trimmed).isPresent()) {
110	            throw nameInUse();
111	        }
112	        String key = contactKey(contact);
113	        if (key != null && people.existsBySheetIdAndContactAndIdNot(sheetId, key, id)) {
114	            throw contactInUse();
115	        }
116	        person.setName(trimmed);
117	        if (gradeFrom != null || !grade.equals(person.gradeOn(today))) {
118	            person.recordGrade(grade, gradeFrom != null ? gradeFrom : today, today);
119	        }
120	        boolean termsChanged = !Objects.equals(terms, person.getTerms());
121	        person.setTerms(terms);
122	        boolean contactChanged = !Objects.equals(key, person.getContact());
123	        person.setContact(key);
124	        Person saved = save(person);
125	        audit.recordOnCommit(record("PERSON_EDITED", by, saved, today)
126	                + (termsChanged ? " terms=" + (terms != null ? terms : "") : "")
127	                + (contactChanged ? " contact=" + (key != null ? key : "") : ""));
128	        rollup.recordChanges(by, sheetId, before);
129	        return saved;
130	    }
131	
132	    /**
133	     * Gives each of the people a grade from the from-date (missing: the sheet's today), in list order, exactly as
134	     * saving each one's edit with that grade would, all or none: one that is not a person of the sheet refuses them
135	     * all. The people as saved, in list order.
136	     */
137	    @Transactional
138	    public List<Person> bulkGrade(String by, String sheetId, Set<Long> ids, String grade, LocalDate from) {
139	        List<Person> chosen = people.findBySheetIdOrderByIdAsc(sheetId).stream()
140	                .filter(p -> ids.contains(p.getId())).toList();
141	        if (chosen.size() != ids.size()) {
142	            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person.");
143	        }
144	        List<Person> saved = new ArrayList<>();
145	        for (Person p : chosen) {
146	            saved.add(update(by, sheetId, p.getId(), p.getVersion(), p.getName(), grade, from, p.getTerms(),
147	                    p.getContact()));
148	        }
149	        return saved;
150	    }
151	
152	    /** Retires the person from the date; a missing date takes the sheet's today. Their claims keep counting. */
153	    @Transactional
154	    public Person retire(String by, String sheetId, Long id, LocalDate from) {
155	        LocalDate today = sheets.load(sheetId).getToday();
156	        LocalDate on = from != null ? from : today;
157	        RollupService.Snapshot before = rollup.snapshot(sheetId);
158	        Person person = people.findWithLockByIdAndSheetId(id, sheetId)
159	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
160	        person.setRetiredFrom(on, today);
161	        Person saved = save(person);
162	        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + by + " name=" + saved.getName()
163	                + " from=" + on);
164	        rollup.recordChanges(by, sheetId, before);
165	        return saved;
166	    }
167	
168	    /**
169	     * Puts a hold on the person from the date (missing: the sheet's today) to the to-date (missing: with no end); the
170	     * holds already put are kept, each ending on its to-date. Their open claims dated within a hold, not bound by a
171	     * statement, count in no live total. Refused when the to-date is before the from-date.
172	     */
173	    @Transactional
174	    public Person hold(String by, String sheetId, Long id, LocalDate from, LocalDate to) {
175	        LocalDate today = sheets.load(sheetId).getToday();
176	        LocalDate on = from != null ? from : today;
177	        if (to != null && to.isBefore(on)) {
178	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A hold cannot end before it starts.");
179	        }
180	        RollupService.Snapshot before = rollup.snapshot(sheetId);
181	        Person person = people.findWithLockByIdAndSheetId(id, sheetId)
182	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
183	        person.addHold(on, to, today);
184	        Person saved = save(person);
185	        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + by + " name=" + saved.getName()
186	                + " from=" + on);
187	        rollup.recordChanges(by, sheetId, before);
188	        return saved;
189	    }
190	
191	    /**
192	     * Gives the person the alias, without surrounding spaces; refused when blank, or when it equals, ignoring case,
193	     * any name or alias on the sheet.
194	     */
195	    @Transactional
196	    public Person addAlias(String by, String sheetId, Long id, String alias) {
197	        String trimmed = alias == null ? "" : alias.strip();
198	        if (trimmed.isEmpty()) {
199	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Enter an alias.");
200	        }
201	        Person person = people.findWithLockByIdAndSheetId(id, sheetId)
202	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
203	        if (people.nameOrAliasInUse(sheetId, trimmed)) {
204	            throw nameInUse();
205	        }
206	        person.addAlias(trimmed);
207	        Person saved = save(person);
208	        audit.recordOnCommit("PERSON_ALIAS_ADDED sheet=" + sheetId + " by=" + by + " name=" + saved.getName()
209	                + " alias=" + trimmed);
210	        return saved;
211	    }
212	
213	    @Transactional(readOnly = true)
214	    public List<Patron> patrons(String sheetId) {
215	        return patrons.findBySheetIdOrderByIdAsc(sheetId);
216	    }
217	
218	    /** Names another person on the sheet as the person's patron; never themselves, nor anyone twice. */
219	    @Transactional
220	    public Patron addPatron(String by, String sheetId, Long id, Long patronId) {
221	        Person person = people.findWithLockByIdAndSheetId(id, sheetId)
222	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
223	        Person patron = people.findByIdAndSheetId(patronId, sheetId)
224	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such patron."));
225	        if (person.getId().equals(patron.getId())) {
226	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A person cannot be their own patron.");
227	        }
228	        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) {
229	            throw patronNamed();
230	        }
231	        Patron added;
232	        try {
233	            added = patrons.saveAndFlush(new Patron(sheetId, person.getId(), patron.getId()));
234	        } catch (DataIntegrityViolationException e) {
235	            throw patronNamed();
236	        }
237	        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + by + " name=" + person.getName()
238	                + " patron=" + patron.getName());
239	        return added;
240	    }
241	
242	    /** A contact as stored: without surrounding spaces and lower-cased; null when blank. */
243	    private static String contactKey(String contact) {
244	        if (contact == null || contact.isBlank()) {
245	            return null;
246	        }
247	        return contact.strip().toLowerCase(Locale.ROOT);
248	    }
249	
250	    /** Saves the person; the store's unique indexes refuse a name or contact another request took meanwhile. */
251	    private Person save(Person person) {
252	        try {
253	            return people.saveAndFlush(person);
254	        } catch (DataIntegrityViolationException e) {
255	            throw nameOrContactInUse();
256	        } catch (ObjectOptimisticLockingFailureException e) {
257	            // another request saved the person between this one reading and writing it
258	            throw stale();
259	        }
260	    }
261	
262	    /** The audit line about a person, with the grade in force on the sheet's today. */
263	    private static String record(String event, String by, Person p, LocalDate today) {
264	        return event + " sheet=" + p.getSheetId() + " by=" + by + " name=" + p.getName() + " grade="
265	                + p.gradeOn(today);
266	    }
267	
268	    private static ResponseStatusException stale() {
269	        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,
270	                "Someone else has saved this person since it was opened.");
271	    }
272	
273	    private static ResponseStatusException patronNamed() {
274	        return new ResponseStatusException(HttpStatus.CONFLICT, "That person is already one of their patrons.");
275	    }
276	
277	    private static ResponseStatusException contactInUse() {
278	        return new ResponseStatusException(HttpStatus.CONFLICT, "That contact is already in use on this sheet.");
279	    }
280	
281	    private static ResponseStatusException nameOrContactInUse() {
282	        return new ResponseStatusException(HttpStatus.CONFLICT,
283	                "That name or contact is already in use on this sheet.");
284	    }
285	
286	    private static ResponseStatusException nameInUse() {
287	        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet.");
288	    }
289	}
