550	/**
551	 * A person on a sheet, with a name (unique on the sheet, ignoring case) and a dated grade (A, B or C): each grade
552	 * applies from its from-date, the first one given from the beginning of time; and the terms of their own, if any.
553	 */
554	@Entity
555	@Table(name = "person")
556	public class Person {
557	
558	    @Id
559	    @GeneratedValue(strategy = GenerationType.IDENTITY)
560	    private Long id;
561	
562	    @Column(name = "sheet_id", nullable = false)
563	    private String sheetId;
564	
565	    @Column(name = "name", nullable = false)
566	    private String name;
567	
568	    @ElementCollection(fetch = FetchType.EAGER)
569	    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
570	    private List<DatedGrade> grades = new ArrayList<>();
571	
572	    @Column(name = "terms")
573	    private Integer terms;
574	
575	    /** The person's contact, without surrounding spaces and lower-cased; null: none. */
576	    @Column(name = "contact")
577	    private String contact;
578	
579	    @Column(name = "retired_from")
580	    private LocalDate retiredFrom;
581	
582	    /** The sheet's today when the person was added; null: before that was kept. */
583	    @Column(name = "added_on")
584	    private LocalDate addedOn;
585	
586	    /** The sheet's today when the retirement date was set; null: before that was kept, or not retired. */
587	    @Column(name = "retired_on")
588	    private LocalDate retiredOn;
589	
590	    @ElementCollection(fetch = FetchType.EAGER)
591	    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
592	    private List<DatedHold> holds = new ArrayList<>();
593	
594	    @ElementCollection(fetch = FetchType.EAGER)
595	    @CollectionTable(name = "person_alias", joinColumns = @JoinColumn(name = "person_id"))
596	    private List<PersonAlias> aliases = new ArrayList<>();
597	
598	    @Version
599	    @Column(name = "version", nullable = false)
600	    private long version;
601	
602	    protected Person() {
603	    }
604	
605	    public Person(String sheetId, String name, String grade) {
606	        this(sheetId, name, grade, null);
607	    }
608	
609	    /** A person added while the sheet's today was the date. */
610	    public Person(String sheetId, String name, String grade, LocalDate addedOn) {
611	        this.sheetId = sheetId;
612	        this.name = name;
613	        this.addedOn = addedOn;
614	        this.grades.add(new DatedGrade(grade, null, addedOn));
615	    }
616	
617	    /**
618	     * The person as they stood at the end of the day, for figures taken as of it: only the grades, holds and
619	     * retirement recorded while the sheet's today was on or before the day. Not to be saved.
620	     */
621	    public Person asOf(LocalDate day) {
622	        Person then = new Person();
623	        then.id = id;
624	        then.sheetId = sheetId;
625	        then.name = name;
626	        then.terms = terms;
627	        then.addedOn = addedOn;
628	        then.version = version;
629	        grades.stream().filter(g -> g.madeBy(day)).forEach(then.grades::add);
630	        if (then.grades.isEmpty()) {
631	            // the first grade they were given stands for them
632	            grades.stream().filter(g -> g.getFrom() == null).forEach(then.grades::add);
633	        }
634	        holds.stream().filter(h -> h.madeBy(day)).forEach(then.holds::add);
635	        then.aliases.addAll(aliases);
636	        if (retiredOn == null || !retiredOn.isAfter(day)) {
637	            then.retiredFrom = retiredFrom;
638	            then.retiredOn = retiredOn;
639	        }
640	        return then;
641	    }
642	
643	    /** Whether the person had been added by the end of the day: added while the sheet's today was on or before it. */
644	    public boolean addedBy(LocalDate day) {
645	        return addedOn == null || !addedOn.isAfter(day);
646	    }
647	
648	    public Long getId() {
649	        return id;
650	    }
651	
652	    public String getSheetId() {
653	        return sheetId;
654	    }
655	
656	    public String getName() {
657	        return name;
658	    }
659	
660	    public void setName(String name) {
661	        this.name = name;
662	    }
663	
664	    /** Every grade recorded for the person, earliest from-date first (the one from the beginning of time first). */
665	    public List<DatedGrade> getGrades() {
666	        return grades.stream().sorted(Comparator.comparing(DatedGrade::getFrom,
667	                Comparator.nullsFirst(Comparator.naturalOrder()))).toList();
668	    }
669	
670	    /** The grade in force on the date: the one with the latest from-date on or before it. */
671	    public String gradeOn(LocalDate date) {
672	        return grades.stream().filter(g -> g.getFrom() == null || (date != null && !g.getFrom().isAfter(date)))
673	                .max(Comparator.comparing(DatedGrade::getFrom, Comparator.nullsFirst(Comparator.naturalOrder())))
674	                .map(DatedGrade::getGrade).orElse(null);
675	    }
676	
677	    /** Records the grade from the date, replacing one already recorded from that same date; the others are kept. */
678	    public void recordGrade(String grade, LocalDate from, LocalDate madeOn) {
679	        grades.removeIf(g -> Objects.equals(g.getFrom(), from));
680	        grades.add(new DatedGrade(grade, from, madeOn));
681	    }
682	
683	    /** The person's own terms in business days: a claim of theirs is due by that many business days after its date; null for none. */
684	    public Integer getTerms() {
685	        return terms;
686	    }
687	
688	    public void setTerms(Integer terms) {
689	        this.terms = terms;
690	    }
691	
692	    public String getContact() {
693	        return contact;
694	    }
695	
696	    public void setContact(String contact) {
697	        this.contact = contact;
698	    }
699	
700	    /** The date the person is retired from; null while they are not retired. */
701	    public LocalDate getRetiredFrom() {
702	        return retiredFrom;
703	    }
704	
705	    /** Retires the person from the date, set while the sheet's today was the made-on date. */
706	    public void setRetiredFrom(LocalDate retiredFrom, LocalDate madeOn) {
707	        this.retiredFrom = retiredFrom;
708	        this.retiredOn = madeOn;
709	    }
710	
711	    /** A person with a retirement date set is retired at once, whatever the date. */
712	    public boolean isRetired() {
713	        return retiredFrom != null;
714	    }
715	
716	    /** Whether the person's retirement date is reached on the day: the day is on or after it. */
717	    public boolean isRetiredOn(LocalDate day) {
718	        return retiredFrom != null && day != null && !day.isBefore(retiredFrom);
719	    }
720	
721	    /** The person's aliases, sorted as names are compared: ignoring case. */
722	    public List<String> getAliases() {
723	        return aliases.stream().map(PersonAlias::getAlias)
724	                .sorted(Comparator.comparing((String a) -> a.toLowerCase(Locale.ROOT)).thenComparing(a -> a))
725	                .toList();
726	    }
727	
728	    /** Gives the person the alias, without surrounding spaces; the ones already given are kept. */
729	    public void addAlias(String alias) {
730	        aliases.add(new PersonAlias(sheetId, alias));
731	    }
732	
733	    /** Every hold put on the person, earliest from-date first. */
734	    public List<DatedHold> getHolds() {
735	        return holds.stream().sorted(Comparator.comparing(DatedHold::getFrom)).toList();
736	    }
737	
738	    /** Whether the person has any hold. */
739	    public boolean isHeld() {
740	        return !holds.isEmpty();
741	    }
742	
743	    /** Puts a hold on the person from the date to the date (null: with no end); the ones already put are kept. */
744	    public void addHold(LocalDate from, LocalDate to, LocalDate madeOn) {
745	        holds.add(new DatedHold(from, to, madeOn));
746	    }
747	
748	    /**
749	     * Whether the claim counts toward the person's live totals: one whose status counts, except an open one dated
750	     * within a hold that no statement binds, or once the person's retirement date is reached on the sheet's today, and
751	     * one deferred on the sheet's today.
752	     */
753	    public boolean countsLive(Claim claim, LocalDate today) {
754	        return claim.getStatus().counts() && !claim.isDeferredOn(today)
755	                && !(claim.getStatus().isOpen() && !claim.isBound()
756	                && (holds.stream().anyMatch(h -> h.covers(claim.getDate())) || isRetiredOn(today)));
757	    }
758	
759	    /**
760	     * Whether the claim counts toward the person's figure for a period ending on the day: one whose status at the end
761	     * of that day counts, left out as the live rules say when deferred on the sheet's today or held.
762	     */
763	    public boolean countsAtEndOf(Claim claim, LocalDate end, LocalDate today) {
764	        ClaimStatus then = claim.statusAtEndOf(end);
765	        return then != null && then.counts() && !claim.isDeferredOn(today)
766	                && !(claim.getStatus().isOpen() && !claim.isBound()
767	                && (holds.stream().anyMatch(h -> h.covers(claim.getDate())) || isRetiredOn(today)));
768	    }
769	
770	    /** The version of the person as stored, raised on each save. */
771	    public long getVersion() {
772	        return version;
773	    }
774	}
